Image *
ReadGroup4Image(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  FILE *file = NULL;
  FILE *temp_file = NULL;
  char temp_filename[MaxTextLength];

  /* Validate input parameters */
  if (!image_info || !exception)
    return NULL;

  /* Open the image file */
  file = fopen(image_info->filename, "rb");
  if (!file) {
    (void) ThrowFileException(exception, FileOpenError, "UnableToOpenFile", image_info->filename);
    return NULL;
  }

  /* Create a temporary file for TIFF output */
  (void) snprintf(temp_filename, sizeof(temp_filename), "%s_temp.tiff", image_info->filename);
  temp_file = fopen(temp_filename, "wb");
  if (!temp_file) {
    (void) fclose(file);
    (void) ThrowFileException(exception, FileOpenError, "UnableToCreateTemporaryFile", temp_filename);
    return NULL;
  }

  /* Write the TIFF headers and image data to the temporary file */
  /* (Implementation of actual reading and writing is abstracted here) */
  {
    unsigned char header[4] = { 'T', 'I', 'F', 'F' };
    if (fwrite(header, 1, sizeof(header), temp_file) != sizeof(header)) {
      (void) fclose(file);
      (void) fclose(temp_file);
      (void) remove(temp_filename);
      (void) ThrowFileException(exception, FileWriteError, "UnableToWriteTIFFHeader", temp_filename);
      return NULL;
    }
  }

  /* Close the source file */
  if (fclose(file) != 0) {
    (void) fclose(temp_file);
    (void) remove(temp_filename);
    (void) ThrowFileException(exception, FileCloseError, "UnableToCloseOperation", image_info->filename);
    return NULL;
  }

  /* Close the temporary file */
  if (fclose(temp_file) != 0) {
    (void) remove(temp_filename);
    (void) ThrowFileException(exception, FileCloseOperation, "UnableToCloseOperation", temp_filename);
    return NULL;
  }

  /* Read the TIFF image from the temporary file into an Image structure */
  image = ReadImage(temp_filename, exception);
  if (!image) {
    (void) remove(temp_filename);
    return NULL;
  }

  /* Clean up the temporary file */
  (void) remove(temp_filename);

  return image;
}

