Image *ReadGroup4Image(const ImageInfo *image_info, ExceptionInfo *exception)
{
    Image *image = NULL;
    FILE *file = (FILE *) NULL;
    MagickBooleanType status;

    (void) exception;

    if (image_info == (ImageInfo *) NULL)
        return (Image *) NULL;

    if ((file = fopen(image_info->filename, "rb")) == (FILE *) NULL)
    {
        ThrowFileException(exception, FileOpenError, "Unable to open input file", image_info->filename);
        return (Image *) NULL;
    }

    image = AcquireImage(image_info, exception);
    if (image == (Image *) NULL)
    {
        (void) fclose(file);
        return (Image *) NULL;
    }

    // Create a temporary file to write the TIFF data
    FILE *tiff_file = tmpfile();
    if (tiff_file == (FILE *) NULL)
    {
        (void) fclose(file);
        DestroyImage(image);
        return (Image *) NULL;
    }

    // Write TIFF headers and image data to the temporary file
    status = WriteTIFFImage(tiff_file, image, exception);
    if (status == MagickFalse)
    {
        (void) fclose(file);
        (void) fclose(tiff_file);
        DestroyImage(image);
        return (Image *) NULL;
    }

    // Rewind the temporary file and read the TIFF image back
    rewind(tiff_file);
    image = ReadTIFFImage(image_info, tiff_file, exception);

    // Clean up resources
    (void) fclose(file);
    (void) fclose(tiff_file);

    if (image == (Image *) NULL)
        return (Image *) NULL;

    // Set the filename and format fields
    image->filename = (char *) AcquireString(image_info->filename);
    image->format = (size_t) TIFFCoderSignature;

    return image;
}
